"""Build the reviewable economy and asset inventory from actual project data."""
import json,zipfile,re
from pathlib import Path
root=Path(__file__).resolve().parents[1]
backup=next((root/'backups').glob('*before-readability-progression-sprint.zip'))
with zipfile.ZipFile(backup) as z:
 def old(name):
  path=next(n for n in z.namelist() if n.replace('\\','/').endswith('/'+name) or n==name)
  return json.loads(z.read(path).decode('utf-8-sig'))
 previous={q['id']:q for q in old('data/RPGManagerStage3.json')['quests']}
data=json.loads((root/'data/RPGManagerStage3.json').read_text())
rows=['# October 15 economy and graphics audit','','## Economy source audit','','The existing sources are authored quest Gold/Arcana/XP; seeded roadside Gold, shrine Arcana and supply finds; completion consumable/common/rare gear rolls; Workshop (1 Gold/minute) and Study (1 Arcana/5 minutes) while the process is open; and resale of unequipped shared stock. Starting resources are 100 Gold, 0 Arcana, 6 Potions and 3 Medkits. No offline income was added. Quests suspend participants’ camp jobs. Recruits fill vacancies for **0 Gold**, including at zero balance.','','Gold sinks: purchases (gear 18–110g), Potion **6g** (was 10g), Medkit **12g** (was 25g), class Armor restoration **2g per missing point**. Gear resale is half purchase price rounded down, consumes exactly one shared-stock item, and cannot reach equipped items. Worn stock keeps its recorded remaining Armor when returned/re-equipped; no item Repair action exists. HP gear does not heal on equip.','','Arcana sinks remain Protection Ward unlock/cast **10/5**, Healing Ritual **20/10**, Greed Prayer **10/10**, Reanimate **100/50**. Reanimation uses existing rules; no recruit fee or alternative economy was introduced. Higher Arcana income makes these reachable while retaining the unlock/cast decision. The inert legacy Ward Focus remains visibly described as inert, avoiding an invented magical item effect.','','Scarcity found: 5–10g short errands could not cover the old 10g Potion plus 25g Medkit; 0–3 Arcana on most routes made Altar progression slow relative to its costs. Gold rewards stay unchanged. Medkit cost now equals two Potions; expensive armor still requires saving. Most Arcana routes roughly double; combat routes with none gain 2 Arcana; cold-shrine finds rise from 1 at 50% to 3 at 80%. Class restoration adds a small recurring Gold sink.','','## Authored preview/reward audit','','Amounts below are victory rewards before seeded finds; draw/defeat tables remain explicit in data. XP is per companion; Recall forfeits completion XP/rewards and retains only acquired finds. Normal play normalizes the retired hidden danger preference to Standard, while active saved trips retain locked amounts.','','| Contract | Minutes | Type | Gold | Arcana before → now | XP each | Potential bonus |','|---|---:|---|---:|---:|---:|---|']
for q in data['quests']:
 bonus=', '.join(f'{k.removesuffix("Chance")}: {v:.0%}' for k,v in q.get('bonusRewards',{}).items()) or 'None'
 rows.append(f"| {q['name']} | {q['durationMinutes']} | {q['combatMode']} | {q['rewardGold']['victory']} | {previous[q['id']]['rewardArcana']['victory']} → {q['rewardArcana']['victory']} | {q['xpReward']} | {bonus} |")
rows+=['','## Representative budgets','','- **1-minute message:** 6g, 0a, 5 XP; buys one Potion. Three such errands reach level 2 (15 XP). Herbs pay 5g with a 50% Potion bonus; safe does not guarantee a fight.','- **3-minute Grave Moss:** 2g, 3a, 8 XP, optional fight. An Arcana-focused route is deliberately weaker for Gold.','- **5-minute Goblin Hunt:** 18g, 2a, 20 XP; covers one Medkit (12g) plus one Potion (6g), or one Potion and up to six missing class-Armor points (12g). Gear purchase requires saving.','- **10-minute Shrine Hunt:** 30g, 4a, 35 XP; one Medkit (12g), two Potions (12g), three restored Armor (6g) consume the whole base payout.','- **15-minute Sunken Crypt:** 65g, 12a, 65 XP; two Medkits (24g), three Potions (18g) and six restored Armor (12g) leave 11g toward gear.','- **15-minute Black Gate boss:** 90g, 20a, 85 XP, five-quest unlock. Three Medkits (36g), three Potions (18g) and six restored Armor (12g) leave 24g. Unlock/cast Reanimation (150a) still requires saving across several successful Arcana routes.','','XP requirements to the next level are **15 / 70 / 150**, cap 4. Level 2 can arrive after one early Hunt or three safe errands. Higher levels require multiple contracts. Arcana and Gold are purposefully not proportional on every route. Workshop/Study opportunity cost and free Rest also matter. These budgets are examples, not proof of balance.','','## Reproducible encounter sample','','`node scripts/playtest_balance_audit.js` runs 100 deterministic trip IDs for each of six routes at levels 1, 2 and 4 (1,800 fresh expeditions). Each starts healthy, with full class defenses, no purchased gear, no jobs or consumables; class composition is the authored Ada/Bram/Cora trio. Black Gate unlock is supplied by the harness. Results: `tests/playtest-balance-results.json`. Negative “HP lost” can reflect legitimate level-up HP gains; this is not a pure damage metric.','','The first sample with the old four-member Gate finale gave level-1 victory 32% and 2.58 Wounded per trip; level-2 victory 89% and 1.40 Wounded. Removing one supporting cultist, retaining the enchanter and unchanged demon, improved level-1 victory to 99% and 0.97 Wounded, and level-2 to 100% and 0.50 Wounded. The approved class baselines were not changed. Bosses still threaten already-Wounded/underprepared parties; those death rules have separate regression tests. Longer Hunts have up to two independently seeded 65% small encounters (one at 10 minutes), at 28%/44% of the existing clock; each has one enemy with 1 HP, 0 Armor, 1 damage and no disabling special. The finale resolves at 58%, return narration queues at 78%, arrival remains exactly 100%. Safe optional journeys retain the old 25%/50%/75% chance bands.','','| Level | Route | Victory % | Wounded/trip | Deaths/trip | Battles/trip | Mean Gold | Mean Arcana |','|---:|---|---:|---:|---:|---:|---:|---:|']
raw=(root/'tests/playtest-balance-results.json').read_bytes()
for r in json.loads(raw.decode('utf-16' if raw.startswith(b'\xff\xfe') else 'utf-8-sig')):
 rows.append(f"| {r['level']} | {r['quest']} | {r['victoryPercent']} | {r['woundedPerTrip']:.2f} | {r['deathsPerTrip']:.2f} | {r['meanBattles']:.2f} | {r['meanGold']:.2f} | {r['meanArcana']:.2f} |")
rows+=['','This measures the fixed starter composition, not all 20 class trios, wounded departures, all gear builds or a long campaign. Native playtesting and further balance feedback remain necessary.','','## Graphics inventory and routing','','No art was generated, replaced or deleted. Credits and exact prompts remain in `docs/Visual_Battle_Art_Prompts.md`, `docs/Cozy_Fantasy_Visual_System.md`, and `context/Monster_Portrait_Asset.md`. All custom assets were already wired; this sprint retained their ordinary routes, corrected item icon selection, and made every shop/equipment/reward item use its data icon or safe fallback. The updated Chromium routes inspect ordinary departure, camp, recruitment, character, shop and results; the battle regression covers every supported atlas family, animation beat, corrupt art and failed sheets.','','| Asset/group | Runtime screen/event | Status / rationale |','|---|---|---|','| `BattleWoodland_v1.webp` | Early forest-road travel; woodland Hunt battlefield | Active cached parallax/background |','| `BattleCavern_v1.webp` | Cemetery/crypt/cavern travel and battles | Active; matched by contract biome metadata |','| `BattleCreatures_v1.webp` | Eight creature families, skirmishes/Hunts/bosses, reanimated silhouettes | Active; alpha bounds and optional bitmap fallbacks retained |','| `CozyGuildCamp.webp` | Camp, page backdrops, secondary illustrations | Active; campsite walkers/job props retained |','| `Actor1_1`–`Actor3_8` pictures | Full-body side-view party actors from Actor1–3 portrait index | Active dynamic lookup; each depends on recruited portraits |','| Actor1–3 face/character sheets | Camp walking, departure/return walking, roster/Tavern/member/results portraits | Active, seeded/authored recruitment reaches all three sheets |','| `RPGManagerMonsters` faces | Legacy monster portraits and reanimation | Compatibility path; atlas preferred in illustrated fights |','| `IconSet.webp` | Every item list/detail/reward plus other MZ UI icons | Active; armor/helmet/shield/amulet now match their item roles; Medkit uses a cross icon |','| Other stock battlers, pictures, characters, tiles and effects | Bundled RPG Maker stock / retained historical scene fallbacks | Intentionally not forced into management screens; sci-fi/unused scenery does not fit this sprint |','','The exhaustive CSV below classifies every image file, including stock assets. Dynamic portrait/side-view lookups are intentional, not dead references. Unselected characters and unused creature families may be harder to encounter but remain reachable through their corresponding recruits/contracts. No duplicated fallback is drawn over loaded art.','','Inventory: `docs/October15_Asset_Inventory.csv`.']
rows.append('\n**Intentionally unused atlas cell:** the Mimic is supported by legacy encounter data and renderer coverage, but none of the current 18 authored contracts selects it during ordinary play. Its existing atlas cell is retained for compatibility; this sprint does not invent a new quest or force an unrelated ambush merely to display it. The other seven creature families have ordinary current-contract routes. Stock monster full-body pictures remain superseded by the custom creature atlas.')
(root/'docs/October15_Economy_Art_Audit.md').write_text('\n'.join(rows).replace('Unselected characters and unused creature families may be harder to encounter but remain reachable through their corresponding recruits/contracts.','Unselected character portraits remain reachable through recruitment. Creature-family reachability is qualified below.')+'\n',encoding='utf-8')
import csv
with (root/'docs/October15_Asset_Inventory.csv').open('w',newline='',encoding='utf-8') as out:
 writer=csv.writer(out);writer.writerow(['path','bytes','route','status'])
 for path in sorted((root/'img').rglob('*')):
  if not path.is_file():continue
  rel=path.relative_to(root).as_posix();name=path.stem;folder=path.parent.name
  route='Bundled stock; no new placement needed';status='Intentionally unused or legacy fallback'
  if name in ['BattleWoodland_v1','BattleCavern_v1','BattleCreatures_v1','CozyGuildCamp']:route='Illustrated travel/battle/camp';status='Active custom art'
  elif folder=='pictures' and re.fullmatch(r'Actor[123]_[1-8]',name):route='Matching full-body party battle actor';status='Active dynamic portrait lookup'
  elif folder in ['faces','characters'] and name in ['Actor1','Actor2','Actor3','RPGManagerMonsters']:route='Roster/recruitment/camp/travel/legacy monster portrait';status='Active dynamic lookup'
  elif folder=='system':route='MZ base UI, system/equipment/item icons';status='Runtime infrastructure / optional UI fallback'
  writer.writerow([rel,path.stat().st_size,route,status])
print('Wrote actual reward/budget audit and exhaustive image inventory.')
changes=[]
with zipfile.ZipFile(backup) as archive:
 entries={n.replace('\\','/'):n for n in archive.namelist()}
 for folder in ['js/plugins','data','context','docs','scripts','tests']:
  for path in sorted((root/folder).glob('*')):
   if not path.is_file() or path.suffix not in ['.js','.py','.json','.md','.csv']:continue
   rel=path.relative_to(root).as_posix();key=next((n for n in entries if n==rel or n.endswith('/'+rel)),None)
   if key is None:changes.append((rel,'Added'))
   elif archive.read(entries[key]).replace(b'\r\n',b'\n')!=path.read_bytes().replace(b'\r\n',b'\n'):changes.append((rel,'Updated'))
manifest=['# October 15 changed source and data files','','Compared against the verified pre-sprint backup; newline-only differences are ignored. No image asset changed. Screenshots and generated test outputs are separate verification artifacts.','','| Path | Change |','|---|---|']+[f'| `{name}` | {status} |' for name,status in changes]
(root/'docs/October15_Changed_Files.md').write_text('\n'.join(manifest)+'\n',encoding='utf-8')
